export class F_twoD_pond {
	static area(x, a_eq, band) {
		if (!(x > 0)) {
			return 0;
		}
		if ((!(band > 0)) || (x >= band)) {
			return a_eq;
		}
		let t = x / band;
		return ((a_eq * t) * t) * (3 - (2 * t));
	}

}

