	refreshReportedSpecies() {
		this.reported_species_names.clear();
		{
			let p = 0;
			{
				for (; p < this.n_pollutants(); p = (p + 1) | 0) {
					this.reported_species_names.push_back(this.pollutant_names.name_of(p).Clone());
				}
			}
		}
		if (this.options.water_age) {
			this.reported_species_names.push_back(cpp.Str.new_CPtr(cpp.R.Lit("__WATER_AGE__")));
		}
		if (this.options.heat_transport) {
			this.reported_species_names.push_back(cpp.Str.new_CPtr(cpp.R.Lit("__TEMPERATURE__")));
		}
		this.reactions.reported_species.clear();
		{
			let m = 0;
			{
				for (; m < this.reactions.n_species(); m = (m + 1) | 0) {
					if ((!this.reactions.report_enabled.empty()) && (!(this.reactions.report_enabled.a[m] !== 0))) {
						continue;
					}
					this.reactions.reported_species.push_back(m);
					this.reported_species_names.push_back(this.reactions.species_name.a[m].Clone());
				}
			}
		}
	}

	n_reported_species() {
		return cpp.L.toI32(this.reported_species_names.size());
	}

	logControlAction(e) {
		if (this.control_log.size() >= SimulationContext.kMaxControlLog) {
			this.control_log_dropped = cpp.L.incUL(this.control_log_dropped);
			return;
		}
		this.control_log.push_back(e.Clone());
	}

	static updateMaxStats(arr, obj_type, idx, value) {
		let candidate = new SimulationContext_MaxStats();
		candidate.obj_type = obj_type;
		candidate.index = idx;
		candidate.value = value;
		{
			let k = 0;
			{
				for (; k < SimulationContext.MAX_STATS; k = (k + 1) | 0) {
					if (Math.abs(candidate.value) > Math.abs(arr.get_Item_i(k).value)) {
						let tmp = SimulationContext_MaxStats.New_rMaxStats(arr.get_Item_i(k));
						arr.get_Item_i(k).Assign(candidate);
						candidate.Assign(tmp);
					}
				}
			}
		}
	}

