	static lstep_bin(dt, rs) {
		let b = 0;
		let edge = 0.5 * rs;
		while ((b < ((LinkData.N_LSTEP_BINS - 1) | 0)) && (dt <= edge)) {
			b = (b + 1) | 0;
			edge = edge * 0.5;
		}
		return b;
	}

	add_lstep_sample(j, dt, dur, rs) {
		let $t1, $t2, $t3;
		let u = cpp.L.toU64(j);
		if ((this.stat_lstep_time.a[cpp.L.ix(u)] <= 0) || (dt < this.stat_lstep_min.a[cpp.L.ix(u)])) {
			this.stat_lstep_min.a[cpp.L.ix(u)] = dt;
		}
		if (dt > this.stat_lstep_max.a[cpp.L.ix(u)]) {
			this.stat_lstep_max.a[cpp.L.ix(u)] = dt;
		}
		($t1 = cpp.L.ix(u), this.stat_lstep_dt_time.a[$t1] = this.stat_lstep_dt_time.a[$t1] + (dt * dur));
		($t2 = cpp.L.ix(u), this.stat_lstep_time.a[$t2] = this.stat_lstep_time.a[$t2] + dur);
		($t3 = cpp.L.ix(cpp.L.addUL(cpp.L.mulUL(u, cpp.L.toU64(LinkData.N_LSTEP_BINS)), cpp.L.toU64(LinkData.lstep_bin(dt, rs)))), this.stat_lstep_bin_time.a[$t3] = this.stat_lstep_bin_time.a[$t3] + dur);
	}

