	isBypassed(j) {
		let uj = cpp.L.toU64(j);
		return (uj < this.bypassed_.size()) && (this.bypassed_.a[cpp.L.ix(uj)] !== 0);
	}

	nodeSumDqdh(n) {
		return new cpp.ArrRef(this.xnode_.sumdqdh.a, n);
	}

