export class F_forcemain {
	static VISCOS = 1.1e-05;
	static getEquivN(model, r_bot, y_full, slope, n_raw) {
		if ((slope <= 0) || (y_full <= 0)) {
			return n_raw;
		}
		{
			switch (model) {
			case 0:
				{
					return (1.067 / r_bot) * cpp.SysMath.Pow_d_d(y_full / slope, 0.04);
				}
			case 1:
				{
					{
						let hrad = y_full / 4;
						let f = F_forcemain.getFricFactor(r_bot, hrad, 1000000000000);
						return Math.sqrt(f / 185) * cpp.SysMath.Pow_d_d(y_full, 0.16666666666666666);
					}
				}
			}
		}
		return n_raw;
	}

	static getRoughFactor(model, r_bot, length_factor) {
		if (length_factor <= 0) {
			length_factor = 1;
		}
		let G = 32.2;
		{
			switch (model) {
			case 0:
				{
					{
						let denom = (1.318 * r_bot) * cpp.SysMath.Pow_d_d(length_factor, 0.54);
						return (denom > 0) ? (G / cpp.SysMath.Pow_d_d(denom, 1.852)) : 0;
					}
				}
			case 1:
				{
					return 1 / (8 * length_factor);
				}
			}
		}
		return 0;
	}

	static getFricFactor(r_bot, hrad, re) {
		if (hrad <= 0) {
			return 0;
		}
		let f = 0;
		if (re < 10) {
			re = 10;
		}
		if (re <= 2000) {
			f = 64 / re;
		} else {
			if (re < 4000) {
				f = F_forcemain.getFricFactor(r_bot, hrad, 4000);
				f = 0.032 + (((f - 0.032) * (re - 2000)) / 2000);
			} else {
				f = (r_bot / 3.7) / (4 * hrad);
				if (re < 10000000000) {
					f = f + (5.74 / cpp.SysMath.Pow_d_d(re, 0.9));
				}
				f = cpp.SysMath.Log10_d(f);
				f = (0.25 / f) / f;
			}
		}
		return f;
	}

}

