	R_Arch = cpp.Ptr.ZERO;
	R_Baskethandle = cpp.Ptr.ZERO;
	R_Circ = cpp.Ptr.ZERO;
	R_Egg = cpp.Ptr.ZERO;
	R_HorizEllipse = cpp.Ptr.ZERO;
	R_Horseshoe = cpp.Ptr.ZERO;
	R_VertEllipse = cpp.Ptr.ZERO;
