export class F_xsect_shape {
	static rectAofY(y, w_max) {
		return y * w_max;
	}

	static trapezAofY(y, y_bot, s_bot) {
		return (y_bot + (s_bot * y)) * y;
	}

	static triangAofY(y, s_bot) {
		return (y * y) * s_bot;
	}

	static parabAofY(y, r_bot) {
		return ((1.3333333333333333 * r_bot) * y) * Math.sqrt(y);
	}

	static powerfuncAofY(y, s_bot, r_bot) {
		return r_bot * cpp.SysMath.Pow_d_d(y, s_bot + 1);
	}

	static rectClosedRofA(a, w_max, a_full) {
		if (a <= 0) {
			return 0;
		}
		let p = w_max + ((2 * a) / w_max);
		if ((a / a_full) > F_xsect.RECT_ALFMAX) {
			p = p + ((((a / a_full) - F_xsect.RECT_ALFMAX) / (1 - F_xsect.RECT_ALFMAX)) * w_max);
		}
		return a / p;
	}

	static rectOpenRofA(a, w_max, s_bot) {
		if (a <= 0) {
			return 0;
		}
		return a / (w_max + (((2 - s_bot) * a) / w_max));
	}

	static trapezRofY(y, y_bot, s_bot, r_bot) {
		if (y === 0) {
			return 0;
		}
		return F_xsect_shape.trapezAofY(y, y_bot, s_bot) / (y_bot + (y * r_bot));
	}

	static triangRofY(y, s_bot, r_bot) {
		return (y * s_bot) / (2 * r_bot);
	}

	static rectClosedWofY(y_norm, w_max) {
		if (y_norm === 1) {
			return 0;
		}
		return w_max;
	}

	static trapezWofY(y, y_bot, s_bot) {
		return y_bot + ((2 * y) * s_bot);
	}

	static triangWofY(y, s_bot) {
		return (2 * s_bot) * y;
	}

	static parabWofY(y, r_bot) {
		return (2 * r_bot) * Math.sqrt(y);
	}

	static powerfuncWofY(y, s_bot, r_bot) {
		return ((s_bot + 1) * r_bot) * cpp.SysMath.Pow_d_d(y, s_bot);
	}

}

