export class F_lid {
	static SURF = 0;
	static SOIL = 1;
	static STOR = 2;
	static PAVE = 3;
	static N_LAYERS = 4;
	static completedUnitStorage(g, u) {
		if (g.type === 6) {
			let top = cpp.M.max_d_d(g.unit_width.a[u], 0.5);
			let height = g.surf_store.a[u];
			let side = g.surf_side_slope.a[u];
			let bottom = top - ((2 * side) * height);
			if (bottom < 0.5) {
				bottom = 0.5;
				side = (0.5 * (top - 0.5)) / height;
			}
			let depth = g.surf_depth.a[u];
			return (((g.area.a[u] / top) * depth) * (bottom + (side * depth))) * g.surf_void_frac.a[u];
		}
		return ((((g.surf_depth.a[u] * g.surf_void_frac.a[u]) + (g.soil_moist.a[u] * g.soil_thick.a[u])) + (g.stor_depth.a[u] * g.stor_void.a[u])) + ((g.pave_depth.a[u] * g.pave_void.a[u]) * (1 - g.pave_imperv_frac.a[u]))) * g.area.a[u];
	}

	static typeCodeToIndex_LID(code) {
		if (code.EqLit(cpp.R.Lit("BC"))) {
			return 0;
		}
		if (code.EqLit(cpp.R.Lit("RG"))) {
			return 1;
		}
		if (code.EqLit(cpp.R.Lit("GR"))) {
			return 2;
		}
		if (code.EqLit(cpp.R.Lit("IT"))) {
			return 3;
		}
		if (code.EqLit(cpp.R.Lit("PP"))) {
			return 4;
		}
		if (code.EqLit(cpp.R.Lit("RB"))) {
			return 5;
		}
		if (code.EqLit(cpp.R.Lit("VS"))) {
			return 6;
		}
		if (code.EqLit(cpp.R.Lit("RD"))) {
			return 7;
		}
		return -1;
	}

	static hasNativeBottom(type_, storage_thickness, storage_ksat) {
		if (type_ === 6) {
			return true;
		}
		if ((((type_ !== 0) && (type_ !== 1)) && (type_ !== 3)) && (type_ !== 4)) {
			return false;
		}
		return (storage_thickness <= 0) || (storage_ksat > 0);
	}

}

